// present.test.ts — one tab at a time, against payloads the SHARED BUILDERS produced.
//
// `fixtures.json` is generated by `mobile/scripts/gen-fixtures.mts`, which calls the seven
// functions in `src/shared/phone/views.ts` — the exact functions the desktop sends from — and
// feeds the `run` channel the owner's real Befallen 4 (Refined) crawl out of
// `tests/fixtures/befallen-run.snapshots.json`. So these are not assertions about a hand-written
// object that looks like a payload; they are assertions about the payload.
//
// WHAT EACH TAB HAS TO GET RIGHT, and what is asserted below:
//   Live       the bar is relative to the TOP row and the percent is a share of the FIGHT.
//   Run        the elapsed clock TICKS between frames, off `startedAt`.
//   Timers     a stated duration counts DOWN, an unstated one counts UP, and both tick.
//   Character  every v2 field is drawn, and Ratio is two decimals.
//   Events     the closed list, newest first — and no chat, because the builder dropped it.

import fixtureFile from './fixtures.json'
import { asProfile } from '../character-types'
import { ago, clock, num, pct, weaponRatio } from './format'
import { liveView, statusLine } from './live'
import { runView } from './run'
import { timersView } from './timers'
import { characterView, itemFacts } from './character'
import { eventsView, newestEventId } from './events'
import type { PhoneBuff, PhoneEvent, PhoneFight, PhoneRespawn, PhoneRun, PhoneStatus } from '@shared/phone/types'

const { now: NOW, payloads } = fixtureFile as unknown as {
  now: number
  payloads: {
    status: PhoneStatus
    fight: PhoneFight
    fightClosed: PhoneFight
    fightNone: null
    run: PhoneRun
    runNone: null
    respawns: PhoneRespawn[]
    buffs: PhoneBuff[]
    events: PhoneEvent[]
    character: unknown
  }
}

// -------------------------------------------------------------------------------- formatters

describe('the formatters', () => {
  test('numbers shrink the way the phone page shrinks them', () => {
    expect(num(940)).toBe('940')
    // `toFixed(1)` on 12.45 gives "12.4", because 12.45 is not 12.45 in binary. That is what the
    // phone page prints too (`render.ts num`), and PARITY WITH THE PAGE is the property that
    // matters here — not a rounding rule this app would then hold alone.
    expect(num(12_450)).toBe('12.4k')
    expect(num(2_000)).toBe('2k')
    expect(num(3_400_000)).toBe('3.4M')
    expect(num(Number.NaN)).toBe('0')
  })

  test('clocks never run negative and grow an hour field only when they need one', () => {
    expect(clock(0)).toBe('0:00')
    expect(clock(41_000)).toBe('0:41')
    expect(clock(247_000)).toBe('4:07')
    expect(clock(3_847_000)).toBe('1:04:07')
    expect(clock(-5000)).toBe('0:00')
  })

  test('ago reads in the largest unit that still says something', () => {
    expect(ago(NOW - 12_000, NOW)).toBe('12s ago')
    expect(ago(NOW - 400_000, NOW)).toBe('6m ago')
    expect(ago(NOW - 10_000_000, NOW)).toBe('2h ago')
    expect(ago(NOW + 5000, NOW)).toBe('0s ago')
  })

  test('a weapon ratio is two decimals, or nothing at all', () => {
    expect(weaponRatio(41, 26)).toBe('1.58')
    expect(weaponRatio(41, undefined)).toBeNull()
    expect(weaponRatio(undefined, 26)).toBeNull()
    // A delay of zero is not a ratio of infinity; it is an absent fact (world-model law 1).
    expect(weaponRatio(41, 0)).toBeNull()
  })
})

// ------------------------------------------------------------------------------------- Live

describe('Live', () => {
  test('the status strip says who and where, and invents nothing', () => {
    expect(statusLine(payloads.status)).toEqual({
      name: 'Primitive',
      detail: 'Lv 60 · CLR/PAL · Befallen 4 (Refined) · in combat'
    })
    expect(statusLine(null)).toEqual({ name: 'EQ Zera', detail: 'Not paired to a PC yet' })
    // A character with no level and no zone gets a SHORTER line, not a line with holes in it.
    expect(statusLine({ at: 1, classes: [], inCombat: false, app: '1.0.0' }).detail).toBe('')
  })

  test('the meter is damage-descending, and the top row fills the bar', () => {
    const view = liveView(payloads.fight)
    expect(view.title).toBe('Fright')
    expect(view.live).toBe(true)
    expect(view.rows.length).toBeGreaterThan(1)
    expect(view.rows[0]!.fill).toBe(1)
    const fills = view.rows.map((r) => r.fill)
    expect(fills).toEqual([...fills].sort((a, b) => b - a))
    expect(view.empty).toBeNull()
  })

  test('the bar is a fraction of the TOP ROW and the percent is a share of the FIGHT', () => {
    const view = liveView(payloads.fight)
    const second = view.rows[1]!
    const raw = payloads.fight.members[1]!
    expect(second.fill).toBeCloseTo(raw.damage / payloads.fight.members[0]!.damage, 6)
    expect(second.share).toBe(pct(raw.share))
    // …and those two are genuinely different numbers, which is the whole reason for the rule.
    expect(second.fill).not.toBeCloseTo(raw.share, 3)
  })

  test('you and a pet are marked, and your own tile is lifted out', () => {
    const view = liveView(payloads.fight)
    expect(view.rows.filter((r) => r.you)).toHaveLength(1)
    expect(view.rows.filter((r) => r.pet)).toHaveLength(1)
    expect(view.stats.map((s) => s.key)).toEqual(['total', 'time', 'you', 'share'])
  })

  test('a closed fight still draws, and says it is not live', () => {
    const view = liveView(payloads.fightClosed)
    expect(view.live).toBe(false)
    expect(view.rows).toHaveLength(1)
  })

  test('no fight is an empty STATE, not an error', () => {
    const view = liveView(payloads.fightNone)
    expect(view.rows).toHaveLength(0)
    expect(view.empty).toBe('No fight yet. Pull something.')
  })
})

// -------------------------------------------------------------------------------------- Run

describe('Run — the owner’s Befallen crawl', () => {
  test('it draws the numbers a person counted', () => {
    const view = runView(payloads.run, NOW)
    expect(view.title).toBe('Befallen')
    expect(view.stats.find((s) => s.key === 'kills')?.value).toBe(String(payloads.run.kills))
    expect(view.stats.find((s) => s.key === 'kpm')?.value).toBe(payloads.run.killsPerMin!.toFixed(1))
    expect(view.named.length).toBeGreaterThan(0)
  })

  test('the named list is newest first — the payload carries it the other way round', () => {
    const view = runView(payloads.run, NOW)
    const stamps = payloads.run.named.map((n) => n.at)
    expect(view.named[0]!.name).toBe(payloads.run.named[payloads.run.named.length - 1]!.name)
    expect(view.named[0]!.when).toBe(ago(stamps[stamps.length - 1]!, NOW))
  })

  test('A LIVE RUN’S CLOCK TICKS BETWEEN FRAMES', () => {
    const live = { ...payloads.run, active: true }
    const first = runView(live, NOW).stats.find((s) => s.key === 'time')!.value
    const later = runView(live, NOW + 61_000).stats.find((s) => s.key === 'time')!.value
    expect(later).not.toBe(first)
    expect(later).toBe(clock(NOW + 61_000 - live.startedAt))
  })

  test('a CLOSED run’s clock does not, because it is over', () => {
    const closed = { ...payloads.run, active: false }
    expect(runView(closed, NOW + 61_000).stats.find((s) => s.key === 'time')!.value).toBe(
      clock(closed.elapsedMs)
    )
  })

  test('a kills-per-minute of null is a dash, never a zero somebody stated', () => {
    const view = runView({ ...payloads.run, killsPerMin: null }, NOW)
    expect(view.stats.find((s) => s.key === 'kpm')?.value).toBe('—')
  })

  test('no run is an empty state', () => {
    const view = runView(payloads.runNone, NOW)
    expect(view.empty).toBe('No run yet. Zone into an instance, or start one on the PC.')
  })
})

// ----------------------------------------------------------------------------------- Timers

describe('Timers', () => {
  test('every respawn row is drawn, soonest first, as the payload ordered them', () => {
    const view = timersView(payloads.respawns, payloads.buffs, NOW)
    expect(view.respawns.map((r) => r.name)).toEqual(payloads.respawns.map((r) => r.mob))
    expect(view.respawnsEmpty).toBeNull()
  })

  test('an OPEN window is marked, and a row with no stated duration counts UP', () => {
    const view = timersView(payloads.respawns, payloads.buffs, NOW)
    const open = view.respawns.find((r) => r.open)
    expect(open).toBeDefined()
    const counting = view.respawns.find((r) => r.up)
    expect(counting).toBeDefined()
    expect(counting!.open).toBe(false)
  })

  test('A RESPAWN COUNTDOWN TICKS BETWEEN FRAMES', () => {
    const pending = payloads.respawns.find((r) => r.dueAt !== undefined && r.dueAt > NOW)!
    const at = timersView([pending], [], NOW).respawns[0]!.time
    const later = timersView([pending], [], NOW + 30_000).respawns[0]!.time
    expect(later).not.toBe(at)
    expect(later).toBe(clock(pending.dueAt! - (NOW + 30_000)))
  })

  test('a window that opens while nothing arrives flips to open on the local clock', () => {
    const pending = payloads.respawns.find((r) => r.dueAt !== undefined && r.dueAt > NOW)!
    expect(timersView([pending], [], NOW).respawns[0]!.open).toBe(false)
    expect(timersView([pending], [], pending.dueAt! + 1000).respawns[0]!.open).toBe(true)
  })

  test('a buff with a deadline counts down; a permanent one counts nothing', () => {
    const view = timersView([], payloads.buffs, NOW)
    const countdown = view.buffs.find((b) => !b.permanent && !b.up)!
    const permanent = view.buffs.find((b) => b.permanent)!
    expect(countdown.time).not.toBe('—')
    expect(permanent.time).toBe('—')
    // …and the countdown moves with the clock.
    expect(timersView([], payloads.buffs, NOW + 60_000).buffs.find((b) => b.key === countdown.key)!.time)
      .not.toBe(countdown.time)
  })

  test('a countdown that has run out reads 0:00 rather than a negative', () => {
    const buff = payloads.buffs.find((b) => b.endsAt !== undefined)!
    expect(timersView([], [buff], buff.endsAt! + 500_000).buffs[0]!.time).toBe('0:00')
  })

  test('nothing at all is two empty states', () => {
    const view = timersView(null, null, NOW)
    expect(view.respawnsEmpty).toBe('No respawn timers yet.')
    expect(view.buffsEmpty).toBe('Nothing is standing on you.')
  })
})

// -------------------------------------------------------------------------------- Character

describe('Character — the tab the app is named after', () => {
  const profile = asProfile(payloads.character)!

  test('the header, the gear list and the rank badges', () => {
    const view = characterView(profile)
    expect(view.name).toBe('Primitive')
    expect(view.detail).toBe('Level 60 · Cleric / Paladin')
    expect(view.gear).toHaveLength(3)
    expect(view.gear[0]!.rank).toBe('+5')
    // An item whose name carried no rank has no badge — ABSENT is not tier 0.
    expect(view.gear[1]!.rank).toBeNull()
    expect(view.gear[0]!.name).toBe('Sword of the Morning')
  })

  test('the "Character with gear" block, its saves and its unsummed rows', () => {
    const view = characterView(profile)
    expect(view.totals[0]).toEqual({ key: 'ac', label: 'AC', value: '447' })
    expect(view.totals.map((s) => s.label)).toContain('Strength')
    expect(view.saves.map((s) => s.label)).toContain('Save vs Fire')
    // A percentage is NOT summed — the values are listed as the items stated them.
    expect(view.unsummed[0]!.value).toBe('31%')
  })

  test('coverage is stated honestly when an item is not in the DB', () => {
    const view = characterView(profile)
    expect(view.coverage).toContain('12 worn items')
    expect(view.coverage).toContain('1 more is not in this app’s item list')
  })

  test('the four scores are drawn when the body carries them, and absent when it does not', () => {
    expect(characterView(profile).scores.map((s) => s.key)).toEqual(['tank', 'dps', 'heal', 'solo'])
    const { scores: _scores, ...noScores } = profile
    expect(characterView(noScores).scores).toHaveLength(0)
  })

  test('the item sheet carries every v2 fact, and Ratio to two decimals', () => {
    const facts = itemFacts(profile.cells[0]!)
    expect(facts.title).toBe('Sword of the Morning')
    expect(facts.rank).toBe('+5')
    expect(facts.flags).toEqual(['MAGIC ITEM', 'LORE ITEM'])
    expect(facts.numbers.map((n) => [n.label, n.value])).toEqual([
      ['AC', '12'],
      ['HP', '90'],
      ['Mana', '45'],
      ['Damage', '41'],
      ['Delay', '26'],
      ['Ratio', '1.58'],
      ['Skill', '1H Slashing']
    ])
    expect(facts.stats.map((s) => s.value)).toEqual(['+15', '31%'])
    expect(facts.effects[0]).toMatchObject({ name: 'Blade of Dawn', detail: 'Combat Effect' })
    expect(facts.exaltations).toEqual(['Keen', 'Sturdy'])
    expect(facts.ornament).toBe('Sword of Skyfire')
    expect(facts.unknownNote).toBeNull()
  })

  test('an item the DB has never heard of SAYS SO rather than showing nothing', () => {
    const facts = itemFacts(profile.cells[2]!)
    expect(facts.numbers).toHaveLength(0)
    expect(facts.unknownNote).toContain('no record of this item')
  })

  test('no character at all is the "run /outputfile inventory" state', () => {
    expect(characterView(null).empty).toContain('/outputfile inventory')
  })
})

// ----------------------------------------------------------------------------------- Events

describe('Events — and the closed list (ruling 5)', () => {
  test('it draws the celebrations, newest first, with an English label', () => {
    const view = eventsView(payloads.events, NOW)
    expect(view.rows.map((r) => r.label)).toEqual(['Boss', 'Level up', 'Wish list', 'Death'])
    expect(view.rows[0]!.title).toBe('Boss defeated')
    expect(view.rows[0]!.subtitle).toBe('Fright')
    expect(view.rows[0]!.when).toBe(ago(payloads.events[0]!.at, NOW))
  })

  test('NO CHAT EVER REACHES THIS TAB — the builder dropped it before it was sealed', () => {
    // The fixture generator offered `phoneEvents` a tell and a guild line alongside the real
    // kinds. They are not in the payload at all, which is the claim this whole feature rests on.
    const kinds = payloads.events.map((e) => e.kind as string)
    expect(kinds).not.toContain('tell')
    expect(kinds).not.toContain('guild')
    expect(eventsView(payloads.events, NOW).rows.map((r) => r.kind)).toEqual(kinds)
  })

  test('the newest id is what a haptic tick watches, not the length', () => {
    expect(newestEventId(payloads.events)).toBe(payloads.events[0]!.id)
    expect(newestEventId([])).toBeNull()
    expect(newestEventId(null)).toBeNull()
    // At the cap, a new event pushes an old one off and the LENGTH does not move.
    const shifted = [{ ...payloads.events[0]!, id: 'fresh' }, ...payloads.events.slice(0, -1)]
    expect(shifted).toHaveLength(payloads.events.length)
    expect(newestEventId(shifted)).not.toBe(newestEventId(payloads.events))
  })

  test('nothing yet is an empty state', () => {
    expect(eventsView(null, NOW).empty).toBe('Nothing to celebrate yet.')
  })
})
